/**
 * Views glob plugin — emulates `import.meta.glob("@/views/<recursive>.vue")`.
 *
 * Rsbuild does not implement `import.meta.glob` natively (the swc parser
 * rejects it as a "critical dependency"). To preserve
 * `src/routers/modules/dynamicRouter.ts` untouched, this plugin scans
 * `src/views` for `.vue` files at build time and generates a virtual module
 * `@yivad/views-glob` exporting the same shape
 * `{ "/src/views/foo/bar.vue": () => import("@/views/foo/bar.vue"), … }`.
 *
 * Lazy `import()` calls in the generated file are statically analyzable so
 * rspack chunk-splits each view as expected.
 */
import { existsSync, mkdirSync, readdirSync, statSync, writeFileSync } from "node:fs";
import { join, relative, resolve, sep } from "node:path";
import type { RsbuildPlugin, RsbuildPluginAPI } from "@rsbuild/core";

const MODULE_ID = "@yivad/views-glob";
const VIEWS_REL = "src/views";

function walkVue(rootDir: string, base = ""): string[] {
  const out: string[] = [];
  let entries: string[] = [];
  try {
    entries = readdirSync(rootDir);
  } catch {
    return out;
  }
  for (const entry of entries) {
    const full = join(rootDir, entry);
    let stat;
    try {
      stat = statSync(full);
    } catch {
      continue;
    }
    if (stat.isDirectory()) {
      out.push(...walkVue(full, base ? `${base}/${entry}` : entry));
    } else if (entry.endsWith(".vue")) {
      out.push(base ? `${base}/${entry}` : entry);
    }
  }
  return out;
}

function buildModule(root: string, files: string[]): string {
  const imports: string[] = [];
  for (const rel of files) {
    const importPath = `@/views/${rel.replace(/\\/g, "/")}`;
    const lookupKey = `/src/views/${rel.replace(/\\/g, "/")}`;
    imports.push(`  ${JSON.stringify(lookupKey)}: () => import(${JSON.stringify(importPath)})`);
  }
  return `// generated by build/views-glob-plugin.ts — do not edit
export default {
${imports.join(",\n")}
};
`;
}

export function viewsGlobPlugin(root: string): RsbuildPlugin {
  const viewsDir = resolve(root, VIEWS_REL);
  const cacheDir = resolve(root, "node_modules", ".cache", "yivad");
  const cacheFile = resolve(cacheDir, "views-glob.js");

  function regenerate() {
    const files = walkVue(viewsDir);
    if (!existsSync(cacheDir)) mkdirSync(cacheDir, { recursive: true });
    writeFileSync(cacheFile, buildModule(root, files), "utf-8");
    return files.length;
  }

  return {
    name: "yivad-views-glob",
    setup(api: RsbuildPluginAPI) {
      api.modifyRsbuildConfig(config => {
        config.resolve = config.resolve ?? {};
        config.resolve.alias = { ...(config.resolve.alias ?? {}), [MODULE_ID]: cacheFile };
      });

      api.onBeforeBuild(() => {
        const n = regenerate();
        process.stdout.write(`  ℹ  views-glob: ${n} view(s) registered\n`);
      });

      api.onBeforeDevCompile(() => {
        regenerate();
      });
    },
  };
}
